title:
var studentName = "Suzy";          // RED(1) — global

function printStudent(studentName) { // BLUE(2) — parameter, shadows RED(1)
    studentName = studentName.toUpperCase();
    console.log(studentName);
}

printStudent("Frank"); // "FRANK"
printStudent(studentName); // "SUZY"
console.log(studentName); // "Suzy" — global 변수는 영향 없음

